var n=`0270-fritule`;var t=`world-0270`;var o=`HR`;var a=`southern-europe`;var s=8;var r=27;var l={en:`Fritule`,ua:`Фритуле`};var g={en:`A traditional Croatia dish made with all-purpose flour, chicken egg, plain yogurt, lemon zest. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Хорватія. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, натуральний йогурт, цедра лимона. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,320,`g`],[`chicken-egg`,2,`pcs`],[`plain-yogurt`,200,`g`],[`white-granulated-sugar`,90,`g`],[`lemon-zest`,5,`g`],[`baking-powder`,8,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`sunflower-oil`,600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,70,`g`]]}];var d={slug:n,id:t,country:`HR`,region:a,servings:8,minutes:27,title:l,text:g,steps:u};export{o as country,d as default,t as id,r as minutes,a as region,s as servings,n as slug,u as steps,g as text,l as title};